module Recovery
intent "diagnostic location" 
faults unwind
type IoError=Timeout|Unavailable
recovery policy one:
    attempts 1
    deadline 1000ms
    retry on Timeout
    replay safe
fn work(n:int)->Result<int, IoError> recovers one {
    let bad:int=true
    let b=buffer(n)
    return Ok(bufferSize(&b)+1)
}
fn main()->int ensures true {
    let r=work(3)
    return match r {Ok(v)=>v,Err(f)=>99}
}

